\title{A Sharp Deterministic Approximate Carath\'eodory Theorem\\
and Its Bridge to Iterated Delaunay Refinement}
\author{Aristotle (Harmonic)}
\date{June 27, 2026}

\begin{document}

\begin{abstract}
The approximate Carath\'eodory theorem states that any point $x = \sum_i p_i V_i$
in the convex hull of vectors of norm at most $R$ in a real inner product space can
be approximated, to squared error $R^2/k$, by the unweighted average of a list of
$k$ of those vectors chosen with repetition. The classical proof---Maurey's
empirical method---is \emph{probabilistic}: it averages over all length-$k$ lists
and concludes that a good list exists, without exhibiting one. We present a fully
constructive companion: an explicit greedy (Frank--Wolfe-type arg-min) procedure
that produces a concrete list and satisfies the \emph{sharper} bound
$\norm{x - \tfrac1k\sum_j V_{\idx(j)}}^2 \le \tau/k \le R^2/k$, where
$\tau = \sum_i p_i\norm{V_i - x}^2 = \sum_i p_i\norm{V_i}^2 - \norm{x}^2$ is the
variance of the family. The deterministic per-step inequality follows from an exact
averaging identity $\sum_i p_i\norm{s + (V_i - x)}^2 = \norm{s}^2 + \tau$, whose
only input is the centroid identity $\sum_i p_i(V_i - x) = 0$. We then connect this
approximation law to iterated Delaunay refinement: any nonnegative sequence that
contracts by a uniform factor $\lambda > 1$ per step decays as $(1/\lambda)^k$,
tends to zero, reaches any tolerance in finitely many steps, and has a finite total
budget $\sum_k d_k \le d_0\lambda/(\lambda-1)$; the one-dimensional minicenter
(midpoint) case realizes this with the sharp factor $\lambda = 2$. All results are
formally verified with zero \texttt{sorry}s.
\end{abstract}

\maketitle

\section{Introduction}

Carath\'eodory's theorem says a point in the convex hull of a set in $\R^n$ is a
convex combination of at most $n+1$ of its points. The \emph{approximate} version
trades exactness for dimension independence: at the cost of a controlled error one
uses a number of points depending only on the desired accuracy, not on the ambient
dimension. This makes it foundational in high-dimensional probability, sparse
approximation, and convex optimization (it is the convergence backbone of the
Frank--Wolfe algorithm).

The standard proof is non-constructive. It interprets the unweighted average of a
random list---each entry drawn i.i.d.\ from the distribution $p$---as an unbiased
estimator of $x$ with variance $\tau/k$, and invokes the probabilistic method:
since the expected error is $\le R^2/k$, some list achieves at most the
expectation. The proof never names that list.

This paper contributes a \textbf{deterministic, verifiable} procedure with a
\textbf{sharper} bound, and situates it within a self-contained theory of refinement
contraction. Section~\ref{sec:prelim} fixes notation; Section~\ref{sec:greedy}
develops the greedy procedure and its $\tau/k$ guarantee; Section~\ref{sec:maurey}
records the probabilistic baseline it strengthens; Section~\ref{sec:contraction}
develops the contraction calculus underlying iterated Delaunay refinement and its
one-dimensional geometric witness; Sections~\ref{sec:algorithms}--\ref{sec:discussion}
give algorithms, applications, and discussion.

\section{Preliminaries}\label{sec:prelim}

Throughout, $E$ is a real inner product space, $\inner{\cdot}{\cdot}$ its inner
product, and $\norm{\cdot}$ the induced norm. The index set $\iota$ is finite and
nonempty. We fix weights $p:\iota\to\R$ with $p_i \ge 0$ and $\sum_i p_i = 1$;
vectors $V:\iota\to E$ (``vertices''); and the target convex point
$x := \sum_j p_j V_j$. We use the real polarization identities
$\norm{a\pm b}^2 = \norm{a}^2 \pm 2\inner{a}{b} + \norm{b}^2$ and
$\inner{a}{a} = \norm{a}^2$.

\begin{definition}[Deviation, \texttt{dev}]
The deviation of vertex $i$ from the target is
$\dev(i) := V_i - x = V_i - \sum_j p_j V_j$.
\end{definition}

\begin{definition}[Variance, \texttt{tau}]
The variance of the family is
$\tau := \sum_i p_i \norm{\dev(i)}^2 = \sum_i p_i \norm{V_i - x}^2$.
\end{definition}

\section{The sharp deterministic procedure}\label{sec:greedy}

\subsection{Structural identities}

\begin{lemma}[Mean-zero deviations, \texttt{sum\_weighted\_dev\_eq\_zero}]
If $\sum_i p_i = 1$ then $\sum_i p_i \dev(i) = 0$.
\end{lemma}
\begin{proof}[Proof sketch]
$\sum_i p_i(V_i - x) = \sum_i p_i V_i - \big(\sum_i p_i\big)x = x - x = 0$.
\end{proof}

\begin{lemma}[Averaging identity, \texttt{avg\_sq\_dev}]\label{lem:avg}
For every $s \in E$, $\sum_i p_i \norm{s + \dev(i)}^2 = \norm{s}^2 + \tau$.
\end{lemma}
\begin{proof}[Proof sketch]
Polarize: $\norm{s+\dev(i)}^2 = \norm{s}^2 + 2\inner{s}{\dev(i)} + \norm{\dev(i)}^2$.
Weight by $p_i$ and sum. The first term gives $\norm{s}^2$, the last gives $\tau$,
and the cross term is $2\inner{s}{\sum_i p_i\dev(i)} = 2\inner{s}{0} = 0$.
\end{proof}

\begin{lemma}[Second-moment form, \texttt{tau\_eq}]\label{lem:taueq}
$\tau = \big(\sum_i p_i\norm{V_i}^2\big) - \norm{x}^2$.
\end{lemma}
\begin{proof}[Proof sketch]
Expand $\norm{V_i - x}^2$, weight, and sum; the cross term is
$2\inner{\sum_i p_i V_i}{x} = 2\norm{x}^2$ and the constant term is $\norm{x}^2$.
\end{proof}

\begin{lemma}[Variance bound, \texttt{tau\_le\_sq}]\label{lem:taule}
If $\norm{V_i} \le R$ for all $i$, then $\tau \le R^2$.
\end{lemma}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:taueq}, $\tau \le \sum_i p_i\norm{V_i}^2 \le \sum_i p_i R^2 = R^2$.
\end{proof}

\subsection{Greedy selection and the sharp bound}

\begin{definition}[Best index and trajectory; \texttt{bestIdx}, \texttt{greedySum}, \texttt{greedyIdx}]
For $s\in E$, $\bestIdx(s) := \arg\min_{i\in\iota}\norm{s + \dev(i)}^2$. The running
sum is $s_0 := 0$, $s_{t+1} := s_t + \dev(\bestIdx(s_t))$, and the chosen indices are
$\idx(t) := \bestIdx(s_t)$.
\end{definition}

\begin{lemma}[Arg-min optimality, \texttt{bestIdx\_spec}]\label{lem:argmin}
For every $i$, $\norm{s + \dev(\bestIdx(s))}^2 \le \norm{s + \dev(i)}^2$.
\end{lemma}

\begin{theorem}[One greedy step, \texttt{step\_bound}]\label{thm:step}
For every $s\in E$, $\norm{s + \dev(\bestIdx(s))}^2 \le \norm{s}^2 + \tau$.
\end{theorem}
\begin{proof}[Proof sketch]
Using Lemma~\ref{lem:argmin}, the arg-min value equals its own $p$-weighted average
$\sum_i p_i\norm{s+\dev(\bestIdx(s))}^2$, which is $\le \sum_i p_i\norm{s+\dev(i)}^2
= \norm{s}^2 + \tau$ by Lemma~\ref{lem:avg}.
\end{proof}

\begin{theorem}[Accumulated bound, \texttt{greedySum\_sq\_le}]\label{thm:acc}
For every $k\in\N$, $\norm{s_k}^2 \le k\tau$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$: $s_0=0$ gives the base; the step is
$\norm{s_{k+1}}^2 \le \norm{s_k}^2 + \tau \le (k+1)\tau$ by Theorem~\ref{thm:step}.
\end{proof}

\begin{lemma}[Trajectory unwinding, \texttt{greedySum\_eq}]\label{lem:unwind}
$s_k = \big(\sum_{t=0}^{k-1} V_{\idx(t)}\big) - k\,x$.
\end{lemma}

\begin{theorem}[Sharp deterministic approximate Carath\'eodory]\label{thm:main}
Let $p_i\ge 0$, $\sum_i p_i = 1$, and $\norm{V_i}\le R$ for all $i$. For any $k\ge 1$,
\[
\norm{\, x - \frac1k \sum_{j=0}^{k-1} V_{\idx(j)} \,}^2
  \;\le\; \frac{\tau}{k} \;\le\; \frac{R^2}{k}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:unwind}, $x - \tfrac1k\sum_j V_{\idx(j)} = -\tfrac1k s_k$, so the
left side equals $\tfrac1{k^2}\norm{s_k}^2 \le \tfrac1{k^2}\cdot k\tau = \tau/k$ by
Theorem~\ref{thm:acc}, and $\tau \le R^2$ by Lemma~\ref{lem:taule}.
\end{proof}

The gap to $R^2/k$ is exactly $\big(R^2 - \sum_i p_i\norm{V_i}^2\big) + \norm{x}^2
\ge \norm{x}^2$ by Lemma~\ref{lem:taueq}, so the bound is strictly sharper unless $x$
is the origin and all vertices lie on the sphere of radius $R$. The list
$\idx(0),\dots,\idx(k-1)$ is produced explicitly, not merely asserted to exist.

\section{The probabilistic baseline}\label{sec:maurey}

\begin{lemma}[Averaging principle, \texttt{exists\_le\_weighted\_average}]
For probability weights $p$ and a real family $g$, some index $i$ satisfies
$g_i \le \sum_j p_j g_j$.
\end{lemma}
\begin{proof}[Proof sketch]
Take $i$ minimizing $g$; then $g_i = \sum_j p_j g_i \le \sum_j p_j g_j$.
\end{proof}

\begin{lemma}[Variance identity, \texttt{weighted\_mean\_sq\_dist}]
$\sum_i p_i\norm{x - V_i}^2 = \big(\sum_i p_i\norm{V_i}^2\big) - \norm{x}^2 = \tau$.
\end{lemma}

\begin{theorem}[Base case; \texttt{maurey\_one\_point}, \texttt{maurey\_one\_point\_variance}]
There is an $i$ with $\norm{x - V_i}^2 \le R^2$, and in fact
$\norm{x - V_i}^2 \le R^2 - \norm{x}^2$.
\end{theorem}

\begin{theorem}[Empirical expectation bound, \texttt{expectation\_bound}]
For $k\ge1$, the product-weighted mean over all lists $\omega\in\iota^k$ (weight
$\prod_j p_{\omega_j}$) of $\norm{x - \tfrac1k\sum_j V_{\omega_j}}^2$ is at most
$R^2/k$.
\end{theorem}
\begin{proof}[Proof sketch]
Write the error as $\tfrac1k\sum_j(x - V_{\omega_j})$, expand into a double sum of
inner products, and marginalize coordinatewise. Off-diagonal terms vanish (because
$\sum_i p_i(x-V_i)=0$); each of the $k$ diagonal terms contributes $\tau\le R^2$;
the $1/k^2$ prefactor leaves $\tau/k \le R^2/k$.
\end{proof}

\begin{theorem}[Approximate Carath\'eodory, \texttt{maurey\_sqrt}]
For $k\ge1$ there exists $f$ with
$\norm{x - \tfrac1k\sum_j V_{f(j)}}^2 \le R^2/k$.
\end{theorem}

Theorem~\ref{thm:main} reproves this rate, replaces the existential $f$ by the
explicit greedy $\idx$, and tightens $R^2/k$ to $\tau/k$.

\section{The contraction calculus}\label{sec:contraction}

\begin{definition}[Contraction process, \texttt{ContractionProcess}]
A sequence $d:\N\to\R$ with factor $\lambda>1$ such that $d_k\ge0$ and
$d_{k+1}\le(1/\lambda)d_k$.
\end{definition}

\begin{theorem}[Exponential contraction, \texttt{diam\_le\_pow}]\label{thm:pow}
$d_k \le (1/\lambda)^k d_0$ for all $k$.
\end{theorem}

\begin{theorem}[Decay and step count; \texttt{diam\_tendsto\_zero}, \texttt{exists\_steps\_below}]
$d_k\to0$, and for every $\varepsilon>0$ there is $N$ with $d_k<\varepsilon$ for all
$k\ge N$.
\end{theorem}

\begin{theorem}[One-dimensional minicenter; \texttt{minicenter\_segment\_halves}, \texttt{segmentBisection}]\label{thm:mini}
For an edge $[a,b]$ the midpoint $m$ satisfies
$\mathrm{dist}(a,m)=\mathrm{dist}(m,b)=\mathrm{dist}(a,b)/2$. Hence edge bisection of
an edge of length $D\ge0$ is a contraction process with $\lambda=2$ and $d_k=D/2^k$,
so $d_k \le (1/2)^k D$; the abstract law is non-vacuous and the exponent achieved.
\end{theorem}

\begin{theorem}[Cumulative budget; \texttt{summable\_of\_contraction}, \texttt{total\_budget}]\label{thm:budget}
If $d_k\le(1/\lambda)^k D$ with $\lambda>1$ and $d_k\ge0$, then $d$ is summable and
$\sum_{k=0}^\infty d_k \le D\lambda/(\lambda-1)$.
\end{theorem}

\begin{theorem}[Covering decay and budget; \texttt{covering\_tendsto\_zero}, \texttt{covering\_budget}]
If $0\le\mathrm{cov}_k\le d_k$ with $d_k\le(1/\lambda)^k D$, then
$\mathrm{cov}_k\to0$ and $\sum_k\mathrm{cov}_k\le D\lambda/(\lambda-1)$.
\end{theorem}

The hypothesis $\mathrm{cov}_k \le d_k$ is supplied by approximate Carath\'eodory:
every domain point lies within one current simplex of an average of its vertices, so
the covering radius is controlled by the simplex diameter and inherits the
contraction.

\section{Algorithms}\label{sec:algorithms}

\textbf{Algorithm A (Greedy sharp Carath\'eodory).} Precompute $x=\sum_i p_i V_i$.
Set $s\leftarrow0$. For $t=0,\dots,k-1$: select $i_t=\arg\min_i\norm{s+(V_i-x)}^2$,
append $i_t$, set $s\leftarrow s+(V_i-x)$. Return $\tfrac1k\sum_t V_{i_t}$, whose
squared error is $\le\tau/k\le R^2/k$ (Theorem~\ref{thm:main}). Cost
$O(k\,|\iota|\,\dim E)$ after $O(|\iota|\dim E)$ precomputation.

\textbf{Algorithm B (Refinement budget estimator).} Given $\lambda>1$, $D=d_0$,
$\varepsilon$, return $N=\lceil\log_\lambda(D/\varepsilon)\rceil$
(Theorem~\ref{thm:pow}) and the total budget $D\lambda/(\lambda-1)$
(Theorem~\ref{thm:budget}).

\section{Applications and discussion}\label{sec:discussion}

Algorithm A yields explicit coresets with the certificate $\tau/k$; the arg-min step
is a Frank--Wolfe linear-minimization oracle and Theorem~\ref{thm:step} its progress
lemma. Theorems~\ref{thm:pow}--\ref{thm:budget} quantify when iterated minicenter
refinement drives mesh fineness and covering error to zero with explicit step counts
and finite cumulative work; Theorem~\ref{thm:mini} pins the sharp 1D factor
$\lambda=2$. The greedy bound makes the empirical method's existence guarantee
redundant in the inner-product setting and sharpens its constant from $R^2$ to the
variance $\tau$, the gap being exactly $\norm{x}^2$ for balanced spherical families.
Open directions include an intrinsic $\norm{x}^2$-governed window for balanced
frames, the $1-1/p$ exponent across $\ell_p$, and a closed-form minicenter factor
$\lambda_d=\sqrt{2(d+1)/d}$ generalizing $\lambda_1=2$.

