from __future__ import annotations
import math, random
from typing import List

Vector = List[float]

def centroid(p, V):
    x = [0.0]*len(V[0])
    for pi, Vi in zip(p, V):
        x = [a+pi*b for a, b in zip(x, Vi)]
    return x

def tau(p, V):
    x = centroid(p, V)
    return sum(pi*sum((a-b)**2 for a,b in zip(Vi,x)) for pi,Vi in zip(p,V))

def greedy_err(p, V, k):
    x = centroid(p, V); dim=len(V[0]); s=[0.0]*dim; idx=[]
    for _ in range(k):
        bi,bv=0,math.inf
        for i in range(len(V)):
            val=sum((s[d]+(V[i][d]-x[d]))**2 for d in range(dim))
            if val<bv: bi,bv=i,val
        idx.append(bi); s=[s[d]+V[bi][d]-x[d] for d in range(dim)]
    avg=[sum(V[i][d] for i in idx)/k for d in range(dim)]
    return sum((x[d]-avg[d])**2 for d in range(dim))

def random_err(p, V, k, trials, rng):
    x=centroid(p,V); dim=len(V[0]); n=len(V); cum=[0.0]
    for pi in p: cum.append(cum[-1]+pi)
    def draw():
        u=rng.random()
        for i in range(n):
            if cum[i]<=u<cum[i+1]: return i
        return n-1
    tot=0.0
    for _ in range(trials):
        avg=[0.0]*dim
        for _ in range(k):
            i=draw()
            for d in range(dim): avg[d]+=V[i][d]/k
        tot+=sum((x[d]-avg[d])**2 for d in range(dim))
    return tot/trials

rng=random.Random(2026)
V=[[2,0],[0,1],[-1,-1],[0.5,2],[1.5,-0.5]]
p=[0.30,0.25,0.20,0.15,0.10]
t=tau(p,V)
print(f"tau={t:.5f}")
print(f"{'k':>3} {'greedy':>12} {'random mean':>14} {'tau/k':>10}")
for k in (1,2,4,8,16,32,64):
    print(f"{k:>3} {greedy_err(p,V,k):>12.8f} "
          f"{random_err(p,V,k,4000,rng):>14.8f} {t/k:>10.6f}")
print("Greedy (deterministic) certificate vs Maurey sampling (in expectation).")
